$:set -euo pipefail
gh auth setup-git
git fetch origin main
git checkout --detach origin/main >/dev/null
DEST='workspaces/shared-conversations/6aec3b14-ad4c-83e8-a6e7-0834eadb34ef/41994534799-1'
TEMP="$(mktemp -d)"
trap 'rm -rf "$TEMP"' EXIT
gh run download 41994534799 --repo BestNameYet/Terminals --name chatgpt-shared-export-final-attestation-41994534799-1 --dir "$TEMP"
node workspaces/extractor-srs-design/acceptance/verify-live-export.js "$DEST" "$TEMP/final-attestation.json"
node - "$DEST" "$TEMP/final-attestation.json" <<'NODE'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const dir=process.argv[2],att=JSON.parse(fs.readFileSync(process.argv[3]));
const names=['response.html','conversation-raw.json','linear-conversation.json','conversation.json','conversation.md','diagnostics.json','receipt.json','execution.json'];
const receipt=JSON.parse(fs.readFileSync(path.join(dir,'receipt.json'))),visible=JSON.parse(fs.readFileSync(path.join(dir,'conversation.json'))),linear=JSON.parse(fs.readFileSync(path.join(dir,'linear-conversation.json'))),diag=JSON.parse(fs.readFileSync(path.join(dir,'diagnostics.json')));
const checked=names.map(name=>{const bytes=fs.readFileSync(path.join(dir,name));const sha=crypto.createHash('sha256').update(bytes).digest('hex');const expected=att.paths.find(x=>x.path===dir+'/'+name);if(!expected||!expected.matched_remote_bytes||expected.bytes!==bytes.length||expected.sha256!==sha)throw Error('Attestation mismatch '+name);return {name,bytes:bytes.length,sha256:sha};});
if(att.verification!=='VERIFIED'||att.run_id!=='41994534799')throw Error('Invalid attestation');
if(visible.coverage!=='selected-visible-only'||visible.source_linear_available!==false)throw Error('Visible coverage not declared');
if(linear.coverage!=='selected-visible-only'||linear.source_linear_available!==false)throw Error('Linear source provenance not declared');
if(visible.messages.length!==11||visible.counts.user!==6||visible.counts.final!==5)throw Error('Expected message count mismatch');
if(diag.coverage!=='selected-visible-only'||diag.source_linear_available!==false)throw Error('Diagnostic coverage missing');
console.log(JSON.stringify({result:'PASS',verified_files:checked.length,attestation:att.verification,publication_commit:att.published_commit_sha,output_directory:dir,source_linear_available:linear.source_linear_available,coverage:visible.coverage,counts:visible.counts,decoder:diag.decoder,receipt_methods:receipt.methods}));
NODE
